        'rationale' => 'The public home page (phase-03 §7.6): the published output of the CMS, not a module\'s UI, so it carries no module: or can: gate (INV-15, D26). `site` closes it for maintenance or when the public site is switched off; only published snapshots render, and a draft is reachable only through the authorised preview routes.',
