        'state_changing' => false,
        'rationale' => 'A published CMS page at /{slug} (phase-03 §7.6), loaded after every other route file. Public by definition (INV-15, D26): only a published, non-trashed page resolves and anything else is a 404; `site` closes it for maintenance or a disabled public site; a draft is reachable only through the authorised preview routes.',
