        'middleware' => ['web', 'capture_referral', 'site', 'site.preview'],
        'permission' => null,
        'panel' => 'public',
        'state_changing' => false,
        'rationale' => 'Authorised inside Site\\PreviewController, not by route middleware (phase-03 §6.12, §9): a valid temporary signature (a reviewer with no account), or a session in good standing holding pages.view. A bad signature is 403, none is 404, and a missing id answers the same as a forbidden one. A route-level can: would refuse the signed-link reviewer the contract requires.',
